#include <zephyr/ztest.h>
#include <zephyr/fs/fcb.h>
#include "fcb_test_common.h"

static struct fcb fcb;

static void *fcb_test_setup(void)
{
	setup_fcb(&fcb);
	return NULL;
}

static void fcb_test_teardown(void)
{
	teardown_fcb(&fcb);
}

ZTEST_SUITE(fcb_append_fill, NULL, fcb_test_setup, NULL, fcb_test_teardown, NULL);

/*
 * Test that fcb_append_fill() fills a sector with as many elements as possible.
 * This test fills two sectors and verifies that the number of elements in each
 * sector is the same, assuming identical element sizes and sector sizes.
 */
ZTEST_USER(fcb_append_fill, test_fcb_append_fill)
{
	int rc;
	uint8_t elem_data[FCB_MAX_ELEM_SIZE];
	uint16_t elem_data_len = sizeof(elem_data);
	int elem_cnts[2];

	/* Initialize element data. */
	for (int i = 0; i < elem_data_len; i++) {
		elem_data[i] = (uint8_t)i;
	}

	/* Fill the first sector. */
	rc = fcb_append_fill(&fcb, elem_data, elem_data_len);
	zassert_true(rc >= 0, "fcb_append_fill failed for first sector: %d", rc);
	elem_cnts[0] = rc;

	/* Fill the second sector. */
	rc = fcb_append_fill(&fcb, elem_data, elem_data_len);
	zassert_true(rc >= 0, "fcb_append_fill failed for second sector: %d", rc);
	elem_cnts[1] = rc;

	/* Verify that both sectors were filled with the same number of elements. */
	/* This assumes that the element size and sector sizes allow for an equal fill. */
	/* If the element size is not a perfect divisor of the available sector space, */
	/* the last element might be smaller, but fcb_append_fill should still report */
	/* the count of full-sized elements. The test expects the count to be equal */
	/* if the sectors are identical and the element size is constant. */	
	zassert_equal(elem_cnts[0], elem_cnts[1], "Element counts in sectors are not equal");

	/* Clear the FCB for subsequent tests. */
	rc = fcb_clear(&fcb);
	zassert_equal(rc, 0, "fcb_clear failed: %d", rc);
}
